        window.render_frame(cx);
        assert_eq!(view.read(cx).state.read(cx).query(cx), "中文");
        window.press("enter", cx);
    })
    .unwrap();
    cx.wait_for(handle.into(), Duration::from_secs(1), |window, _| {
        window.find(id).expanded() == Some(false)
    })
