#[gpui_kit::test]
fn typing_updates_the_owner_after_unrelated_redraws(cx: &mut TestAppContext) {
    cx.update(gpui_kit::init);
    let mut settings = None;
    let (_root, cx) = cx.add_window_view(|window, cx| {
        let view = cx.new(|cx| Settings::new(window, cx));
        settings = Some(view.clone());
        Root::new(view, window, cx)
    });
    let settings = settings.unwrap();
    cx.update(|window, cx| {
        let input = settings.read(cx).name.clone();
        input.update(cx, |input, cx| input.focus(window, cx));
    });
    cx.simulate_keystrokes("a");
    settings.read_with(cx, |view, _| {
        assert_eq!(view.preview.as_ref(), "a");
        assert_eq!(view.changes, 1);
    });
    settings.update(cx, |_, cx| cx.notify());
    cx.simulate_keystrokes("b");
    settings.read_with(cx, |view, _| {
        assert_eq!(view.preview.as_ref(), "ab");
        assert_eq!(view.changes, 2);
    });
}

//! Opt-in headless observation built exclusively on public GPUI APIs.
//!
//! Native accessibility properties are read automatically. Applications register
//! identified GPUI elements with `.test_support()`, without supplying test-only state.
use gpui::{
    App, Bounds, Element, ElementId, FocusHandle, GlobalElementId, Hitbox, InspectorElementId,
    InteractiveElement, IntoElement, LayoutId, Pixels, SharedString, Visibility, Window, px,
};
use std::{
    cell::RefCell,
    collections::HashMap,
    fmt,
    rc::{Rc, Weak},
};

/// Owned facts from the last paint of an observed element.
#[derive(Clone)]
pub struct ElementSnapshot {
    role: Option<gpui::Role>,
    path: Vec<ElementId>,
    checked: Option<bool>,
    indeterminate: Option<bool>,
    selected: Option<bool>,
    expanded: Option<bool>,
    value: Option<SharedString>,
    bounds: Bounds<Pixels>,
    visible: bool,
    focused: Option<bool>,
    focus_action: bool,
    disabled: Option<bool>,
    label: Option<SharedString>,
}
impl fmt::Debug for ElementSnapshot {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        struct BindingMissed;
        impl fmt::Debug for BindingMissed {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                f.write_str("<binding missed>")
            }
        }
        let focused: &dyn fmt::Debug = if self.focused.is_none() && self.focus_action {
            &BindingMissed
        } else {
            &self.focused
        };
        f.debug_struct("ElementSnapshot")
            .field("role", &self.role)
            .field("path", &self.path)
            .field("checked", &self.checked)
            .field("indeterminate", &self.indeterminate)
            .field("selected", &self.selected)
            .field("expanded", &self.expanded)
            .field("value", &self.value)
            .field("bounds", &self.bounds)
            .field("visible", &self.visible)
            .field("focused", focused)
            .field("focus_action", &self.focus_action)
            .field("disabled", &self.disabled)
            .field("label", &self.label)
            .finish()
    }
}

impl ElementSnapshot {
    pub fn role(&self) -> Option<gpui::Role> {
        self.role
    }
    pub fn path(&self) -> &[ElementId] {
        &self.path
    }
    pub fn checked(&self) -> Option<bool> {
        self.checked
    }
    pub fn indeterminate(&self) -> Option<bool> {
        self.indeterminate
    }
    pub fn selected(&self) -> Option<bool> {
        self.selected
    }
    pub fn expanded(&self) -> Option<bool> {
        self.expanded
    }
    /// The native accessibility value, not rendered text or pixels.
    pub fn value(&self) -> Option<&str> {
        self.value.as_deref()
    }

    pub fn bounds(&self) -> Bounds<Pixels> {
        self.bounds
    }
    pub fn visible(&self) -> bool {
        self.visible
    }
    /// Whether the tracked focus scope contains the current keyboard focus.
    /// `None` means no focus binding or native focus capability was observed.
    /// Panics if the native element advertises `Action::Focus` but its binding was missed.
    /// Custom elements omitting that action cannot be diagnosed and may return `None`.
    pub fn focused(&self) -> Option<bool> {
        assert!(
            self.focused.is_some() || !self.focus_action,
            "focus binding was not observed for {:?}; use .test_support().track_focus(&handle). GPUI does not expose pre-existing or implicit focus handles",
            self.path
        );
        self.focused
    }
    /// `None` means the native element does not expose a disabled flag.
    /// Absence is not evidence that a control accepts input.
    pub fn disabled(&self) -> Option<bool> {
        self.disabled
    }
    /// The accessibility label; it can intentionally differ from visible text.
    pub fn label(&self) -> Option<&str> {
        self.label.as_deref()
    }
}

// Each Window owns a distinct Arc<WindowTextSystem>, stable even during initial
// drawing before the Window itself is boxed. Its identity distinguishes equal
// WindowIds in different Apps. Entries never own a Window or a view.
type WindowKey = usize;
type Registry = HashMap<WindowKey, HashMap<GlobalElementId, Weak<Registration>>>;
thread_local! { static REGISTRY: RefCell<Registry> = RefCell::new(HashMap::new()); }

#[doc(hidden)]
pub struct Registration {
    window: WindowKey,
    global_id: GlobalElementId,
    facts: RefCell<ElementSnapshot>,
}
impl Drop for Registration {
    fn drop(&mut self) {
        let _ = REGISTRY.try_with(|registry| {
            if let Ok(mut registry) = registry.try_borrow_mut() {
                if let Some(entries) = registry.get_mut(&self.window) {
                    entries.remove(&self.global_id);
                    if entries.is_empty() {
                        registry.remove(&self.window);
                    }
                }
            }
        });
    }
}

/// Internal lookup used by Kit's testing API. Scope follows GPUI's element path.
#[doc(hidden)]
pub fn find(window: &Window, scope: &[ElementId], id: &ElementId) -> Option<ElementSnapshot> {
    REGISTRY.with(|registry| {
        let registry = registry.borrow();
        let entries = registry.get(&(std::sync::Arc::as_ptr(window.text_system()) as usize))?;
        let matches: Vec<_> = entries
            .values()
            .filter_map(Weak::upgrade)
            .filter(|entry| {
                entry.global_id.len() > scope.len()
                    && entry.global_id.starts_with(scope)
                    && entry.global_id.last() == Some(id)
            })
            .collect();
        assert!(
            matches.len() <= 1,
            "ambiguous ElementId {id:?}; use within(...) to select a scope. Matches: {:?}",
            matches
                .iter()
                .map(|entry| &entry.global_id)
                .collect::<Vec<_>>()
        );
        matches.first().map(|entry| entry.facts.borrow().clone())
    })
}

#[doc(hidden)]
pub fn snapshots(window: &Window) -> Vec<ElementSnapshot> {
    REGISTRY.with(|registry| {
        registry
            .borrow()
            .get(&(std::sync::Arc::as_ptr(window.text_system()) as usize))
            .map(|entries| {
                entries
                    .values()
                    .filter_map(Weak::upgrade)
                    .map(|entry| entry.facts.borrow().clone())
                    .collect()
            })
            .unwrap_or_default()
    })
}

/// Internal focus membership check; unsupported bindings are not evidence of focus.
#[doc(hidden)]
pub fn has_observed_focus(window: &Window, scope: &[ElementId]) -> bool {
    snapshots(window)
        .iter()
        .any(|element| element.path.starts_with(scope) && element.focused == Some(true))
}

/// Resolves a scope even when only its descendants are observed.
#[doc(hidden)]
pub fn scope(window: &Window, parent: &[ElementId], id: &ElementId) -> Vec<ElementId> {
    let mut paths = std::collections::HashSet::new();
    for snapshot in snapshots(window) {
        if !snapshot.path.starts_with(parent) {
            continue;
        }
        for index in parent.len()..snapshot.path.len() {
            if &snapshot.path[index] == id {
                paths.insert(snapshot.path[..=index].to_vec());
            }
        }
    }
    assert_eq!(
        paths.len(),
        1,
        "expected one scope {id:?} below {parent:?}, found {}. Registered paths: {}",
        paths.len(),
        registered_paths(window)
    );
    paths.into_iter().next().unwrap()
}

#[doc(hidden)]
pub fn registered_paths(window: &Window) -> String {
    let mut paths: Vec<_> = snapshots(window)
        .iter()
        .map(|entry| format!("{:?}", entry.path))
        .collect();
    paths.sort();
    if paths.is_empty() {
        "<none; draw a frame and observe elements>".into()
    } else {
        paths.join(", ")
    }
}

/// Transparent forwarding element. Its registration is owned by GPUI element
/// state, so normal state cleanup and cached-view replay determine its lifetime.
pub struct Observed<E> {
    inner: E,
    focus: Option<FocusHandle>,
}
impl<E: Element> Observed<E> {
    /// Repeated observation keeps one registration and the same native identity.
    pub fn test_support(self) -> Self {
        self
    }

    /// Changes the native identity while keeping observation outside GPUI's
    /// stateful wrapper, so later focus bindings still reach this element.
    pub fn id(self, id: impl Into<ElementId>) -> Observed<gpui::Stateful<E>>
    where
        E: InteractiveElement,
    {
        Observed {
            inner: self.inner.id(id),
            focus: self.focus,
        }
    }

    pub(crate) fn new(inner: E) -> Self {
        assert!(
            Element::id(&inner).is_some(),
            "test_support requires an existing ElementId"
        );
        Self { inner, focus: None }
    }
}
impl<E: Element<PrepaintState = Option<Hitbox>> + InteractiveElement> IntoElement for Observed<E> {
    type Element = Self;
    fn into_element(self) -> Self {
        self
    }
}
impl<E: Element<PrepaintState = Option<Hitbox>> + InteractiveElement> Element for Observed<E> {
    type RequestLayoutState = E::RequestLayoutState;
    type PrepaintState = (Option<Hitbox>, Rc<Registration>);
    fn id(&self) -> Option<ElementId> {
        Element::id(&self.inner)
    }
    fn source_location(&self) -> Option<&'static std::panic::Location<'static>> {
        self.inner.source_location()
    }
    fn request_layout(
        &mut self,
        id: Option<&GlobalElementId>,
        inspector: Option<&InspectorElementId>,
        window: &mut Window,
        cx: &mut App,
    ) -> (LayoutId, Self::RequestLayoutState) {
        self.inner.request_layout(id, inspector, window, cx)
    }
    fn prepaint(
        &mut self,
        id: Option<&GlobalElementId>,
        inspector: Option<&InspectorElementId>,
        bounds: Bounds<Pixels>,
        layout: &mut Self::RequestLayoutState,
        window: &mut Window,
        cx: &mut App,
    ) -> Self::PrepaintState {
        let global_id = id.expect("observed elements have an ID");
        let role = self.inner.a11y_role();
        let mut node = gpui::accesskit::Node::new(role.unwrap_or(gpui::Role::Unknown));
        self.inner.write_a11y_info(&mut node);
        let toggled = node.toggled();
        let facts = ElementSnapshot {
            role,
            path: global_id.to_vec(),
            checked: toggled.map(|value| value == gpui::accesskit::Toggled::True),
            indeterminate: toggled.map(|value| value == gpui::accesskit::Toggled::Mixed),
            selected: node.is_selected(),
            expanded: node.is_expanded(),
            value: node.value().map(|value| value.to_owned().into()),
            bounds,
            visible: false,
            focused: None,
            focus_action: node.supports_action(gpui::accesskit::Action::Focus),
            disabled: node.is_disabled().then_some(true),
            label: node.label().map(|label| label.to_owned().into()),
        };
        let registration =
            window.with_element_state(global_id, |state: Option<Rc<Registration>>, window| {
                let registration = state.unwrap_or_else(|| {
                    Rc::new(Registration {
                        window: std::sync::Arc::as_ptr(window.text_system()) as usize,
                        global_id: global_id.clone(),
                        facts: RefCell::new(facts.clone()),
                    })
                });
                *registration.facts.borrow_mut() = facts;
                REGISTRY.with(|registry| {
                    registry
                        .borrow_mut()
                        .entry(registration.window)
                        .or_default()
                        .insert(global_id.clone(), Rc::downgrade(&registration));
                });
                (registration.clone(), registration)
            });
        (
            self.inner
                .prepaint(id, inspector, bounds, layout, window, cx),
            registration,
        )
    }
    fn paint(
        &mut self,
        id: Option<&GlobalElementId>,
        inspector: Option<&InspectorElementId>,
        bounds: Bounds<Pixels>,
        layout: &mut Self::RequestLayoutState,
        paint: &mut Self::PrepaintState,
        window: &mut Window,
        cx: &mut App,
    ) {
        let style = self
            .inner
            .interactivity()
            .compute_style(id, paint.0.as_ref(), window, cx);
        let clipped = bounds
            .intersect(&window.content_mask().bounds)
            .intersect(&Bounds::new(Default::default(), window.viewport_size()));
        {
            let mut facts = paint.1.facts.borrow_mut();
            facts.visible = style.visibility != Visibility::Hidden
                && style.opacity.unwrap_or(1.) > 0.
                && clipped.size.width > px(0.)
                && clipped.size.height > px(0.);
            facts.focused = self
                .focus
                .as_ref()
                .map(|focus| focus.contains_focused(window, cx));
        }
        self.inner
            .paint(id, inspector, bounds, layout, &mut paint.0, window, cx);
    }
    fn a11y_role(&self) -> Option<gpui::Role> {
        self.inner.a11y_role()
    }
    fn write_a11y_info(&self, node: &mut gpui::accesskit::Node) {
        self.inner.write_a11y_info(node);
    }
    fn a11y_synthetic_children(
        &mut self,
        paint: &mut Self::PrepaintState,
        builder: &mut gpui::A11ySubtreeBuilder,
    ) {
        self.inner.a11y_synthetic_children(&mut paint.0, builder);
    }
}

impl<E: Element<PrepaintState = Option<Hitbox>> + InteractiveElement + gpui::Styled> gpui::Styled
    for Observed<E>
{
    fn style(&mut self) -> &mut gpui::StyleRefinement {
        self.inner.style()
    }
}
impl<E: Element<PrepaintState = Option<Hitbox>> + InteractiveElement> InteractiveElement
    for Observed<E>
{
    fn interactivity(&mut self) -> &mut gpui::Interactivity {
        self.inner.interactivity()
    }
    fn track_focus(mut self, focus: &FocusHandle) -> Self {
        self.focus = Some(focus.clone());
        self.inner = self.inner.track_focus(focus);
        self
    }
}
impl<E: Element<PrepaintState = Option<Hitbox>> + InteractiveElement + gpui::ParentElement>
    gpui::ParentElement for Observed<E>
{
    fn extend(&mut self, elements: impl IntoIterator<Item = gpui::AnyElement>) {
        self.inner.extend(elements);
    }
}

impl<E: Element<PrepaintState = Option<Hitbox>> + gpui::StatefulInteractiveElement>
    gpui::StatefulInteractiveElement for Observed<E>
{
}

//! Panel doubles shared by the skin's tests.
//!
//! This lives beside the production modules rather than inside one module's
//! `mod tests` because the same double is needed by two of them: a tab group
//! and a tiles canvas each hand a panel to a different frame, and the question
//! — did the panel get a height? — is the same. Mirrors
//! `gpui_base::dock::test_support`.

use std::{cell::Cell, rc::Rc};

use gpui::{
    App, AppContext as _, Context, Entity, EventEmitter, FocusHandle, Focusable, IntoElement,
    Pixels, Render, Styled as _, Window, div,
};
use gpui_base::dock::PanelEvent;

use crate::{ElementExt as _, dock::Panel};

/// A panel that records the height its container actually gave it.
///
/// The defect it exists for is invisible to every behavioral test: a panel
/// whose content region resolves to zero height still activates, still
/// persists, and still opens a window. Only a measurement sees it.
pub(crate) struct MeasuredProbe {
    focus_handle: FocusHandle,
    height: Rc<Cell<Pixels>>,
}

impl MeasuredProbe {
    pub(crate) fn new(height: Rc<Cell<Pixels>>, cx: &mut App) -> Entity<Self> {
        cx.new(|cx| Self {
            focus_handle: cx.focus_handle(),
            height,
        })
    }
}

impl gpui_base::dock::Panel for MeasuredProbe {
    fn panel_name(&self) -> &'static str {
        "MeasuredProbe"
    }
}

impl Panel for MeasuredProbe {}
impl EventEmitter<PanelEvent> for MeasuredProbe {}

impl Focusable for MeasuredProbe {
    fn focus_handle(&self, _: &App) -> FocusHandle {
        self.focus_handle.clone()
    }
}

impl Render for MeasuredProbe {
    fn render(&mut self, _: &mut Window, _: &mut Context<Self>) -> impl IntoElement {
        let height = self.height.clone();
        div()
            .size_full()
            .on_prepaint(move |bounds, _, _| height.set(bounds.size.height))
    }
}

/// A probe that records the whole box it was given, not only its height.
///
/// A dock's fault is a width fault -- a dock that never states its extent stops
/// being a column and takes whatever the row hands it -- so asking about it
/// needs the measurement `MeasuredProbe` does not keep.
pub(crate) struct SizedProbe {
    focus_handle: FocusHandle,
    size: Rc<Cell<gpui::Size<Pixels>>>,
}

impl SizedProbe {
    pub(crate) fn new(size: Rc<Cell<gpui::Size<Pixels>>>, cx: &mut App) -> Entity<Self> {
        cx.new(|cx| Self {
            focus_handle: cx.focus_handle(),
            size,
        })
    }
}

impl gpui_base::dock::Panel for SizedProbe {
    fn panel_name(&self) -> &'static str {
        "SizedProbe"
    }
}

impl Panel for SizedProbe {}
impl EventEmitter<PanelEvent> for SizedProbe {}

impl Focusable for SizedProbe {
    fn focus_handle(&self, _: &App) -> FocusHandle {
        self.focus_handle.clone()
    }
}

impl Render for SizedProbe {
    fn render(&mut self, _: &mut Window, _: &mut Context<Self>) -> impl IntoElement {
        let size = self.size.clone();
        div()
            .size_full()
            .on_prepaint(move |bounds, _, _| size.set(bounds.size))
    }
}

/// A [`MeasuredProbe`] whose `visible` can be switched off.
///
/// Hiding the only panel of a slot is the one edit that takes a whole slot out
/// of a split without changing the tree, so it is the only way to ask whether
/// the *drawn* slots still fill the split.
pub(crate) struct HideableProbe {
    focus_handle: FocusHandle,
    visible: bool,
    height: Rc<Cell<Pixels>>,
}

impl HideableProbe {
    pub(crate) fn new(height: Rc<Cell<Pixels>>, cx: &mut App) -> Entity<Self> {
        cx.new(|cx| Self {
            focus_handle: cx.focus_handle(),
            visible: true,
            height,
        })
    }

    pub(crate) fn set_visible(&mut self, visible: bool, cx: &mut Context<Self>) {
        self.visible = visible;
        cx.notify();
    }
}

impl gpui_base::dock::Panel for HideableProbe {
    fn panel_name(&self) -> &'static str {
        "HideableProbe"
    }

    fn visible(&self, _: &App) -> bool {
        self.visible
    }
}

impl Panel for HideableProbe {}
impl EventEmitter<PanelEvent> for HideableProbe {}

impl Focusable for HideableProbe {
    fn focus_handle(&self, _: &App) -> FocusHandle {
        self.focus_handle.clone()
    }
}

impl Render for HideableProbe {
    fn render(&mut self, _: &mut Window, _: &mut Context<Self>) -> impl IntoElement {
        let height = self.height.clone();
        div()
            .size_full()
            .on_prepaint(move |bounds, _, _| height.set(bounds.size.height))
    }
}

//! Panel doubles shared by the dock's tests.
//!
//! This lives beside the production modules rather than inside one module's
//! `mod tests` so `tab_group`, `dock_area`, and the cutover tests can share a
//! single panel double and a single ordered delivery log. Ported from the
//! `TabPanel` tests in `crates/component/src/dock/tab_panel.rs`.

use std::sync::{Arc, Mutex};

use gpui::{
    App, AppContext as _, Context, Empty, Entity, EventEmitter, FocusHandle, Focusable,
    IntoElement, Render, TestAppContext, VisualTestContext, WeakEntity, Window,
};

use super::layout::{NodeId, PanelId};
use super::panel::{Panel, PanelEvent, PanelView};
use super::tab_group::{TabGroup, TabGroupConstraints};

/// One thing a panel was told, in delivery order.
///
/// `set_active` and the membership callbacks share one log because their
/// relative order is itself part of the contract under test: a panel joining a
/// group must see `Added` before it is told it is active.
///
/// `Removed` is also where a deliberate divergence from `crates/component` shows up.
/// The old `TabPanel::detach_panel` calls `on_removed` on every detach,
/// including the detach half of a drag between groups, so a moved panel is
/// told it was removed and then added again. In the tree world a move never
/// leaves the tree — `PaneTree::move_panel` reports no `removed_panels`, and
/// `EditResult::removed_panels` documents that a moved panel is absent from it
/// precisely so its entity survives. So under the new contract a moved panel
/// must never see `Removed`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum PanelSignal {
    Active(bool),
    Zoomed(bool),
    Added,
    Removed,
}

/// Shared, cross-panel ordered log of everything the panels were told.
pub(crate) type Log = Arc<Mutex<Vec<(&'static str, PanelSignal)>>>;

pub(crate) fn log_of() -> Log {
    Log::default()
}

/// Take everything logged so far, leaving the log empty.
pub(crate) fn drain(log: &Log) -> Vec<(&'static str, PanelSignal)> {
    std::mem::take(&mut *log.lock().unwrap())
}

/// [`drain`], keeping only the `set_active` edges. Most tests care about the
/// active-state contract and would otherwise have to filter the membership
/// callbacks out by hand at every assertion.
pub(crate) fn drain_active(log: &Log) -> Vec<(&'static str, bool)> {
    drain(log)
        .into_iter()
        .filter_map(|(name, signal)| match signal {
            PanelSignal::Active(active) => Some((name, active)),
            _ => None,
        })
        .collect()
}

pub(crate) struct TestPanel {
    name: &'static str,
    focus_handle: FocusHandle,
    log: Log,
    visible: bool,
    zoomable: bool,
    pub(crate) group: Option<WeakEntity<TabGroup>>,
}

impl TestPanel {
    /// A panel whose deliveries go nowhere. For tests that only need a panel
    /// to exist.
    pub(crate) fn new(name: &'static str, cx: &mut App) -> Entity<Self> {
        Self::logging(name, &log_of(), cx)
    }

    pub(crate) fn logging(name: &'static str, log: &Log, cx: &mut App) -> Entity<Self> {
        let log = log.clone();
        cx.new(|cx| Self {
            name,
            focus_handle: cx.focus_handle(),
            log,
            visible: true,
            zoomable: true,
            group: None,
        })
    }

    pub(crate) fn set_visible(&mut self, visible: bool, cx: &mut Context<Self>) {
        self.visible = visible;
        cx.notify();
    }

    /// A panel that refuses to zoom, which its group must honour.
    pub(crate) fn set_zoomable(&mut self, zoomable: bool, cx: &mut Context<Self>) {
        self.zoomable = zoomable;
        cx.notify();
    }

    fn record(&self, signal: PanelSignal) {
        self.log.lock().unwrap().push((self.name, signal));
    }
}

impl Panel for TestPanel {
    /// The panel's own name, so a dumped layout is legible in assertions.
    fn panel_name(&self) -> &'static str {
        self.name
    }

    fn visible(&self, _: &App) -> bool {
        self.visible
    }

    fn zoomable(&self, _: &App) -> bool {
        self.zoomable
    }

    fn set_active(&mut self, active: bool, _: &mut Window, _: &mut Context<Self>) {
        self.record(PanelSignal::Active(active));
    }

    fn set_zoomed(&mut self, zoomed: bool, _: &mut Window, _: &mut Context<Self>) {
        self.record(PanelSignal::Zoomed(zoomed));
    }

    fn on_added_to(&mut self, group: WeakEntity<TabGroup>, _: &mut Window, _: &mut Context<Self>) {
        self.group = Some(group);
        self.record(PanelSignal::Added);
    }

    fn on_removed(&mut self, _: &mut Window, _: &mut Context<Self>) {
        self.group = None;
        self.record(PanelSignal::Removed);
    }
}

impl EventEmitter<PanelEvent> for TestPanel {}

impl Focusable for TestPanel {
    fn focus_handle(&self, _: &App) -> FocusHandle {
        self.focus_handle.clone()
    }
}

impl Render for TestPanel {
    fn render(&mut self, _: &mut Window, _: &mut Context<Self>) -> impl IntoElement {
        Empty
    }
}

pub(crate) fn panel_id(panel: &Entity<TestPanel>, cx: &TestAppContext) -> PanelId {
    cx.read(|cx| Arc::new(panel.clone()).panel_id(cx))
}

/// Open a window holding one tab group over freshly built panels named
/// `names`, with the first tab displayed.
pub(crate) fn build_group<'a>(
    log: &Log,
    names: &[&'static str],
    cx: &'a mut TestAppContext,
) -> (
    Entity<TabGroup>,
    Vec<Entity<TestPanel>>,
    &'a mut VisualTestContext,
) {
    let (group, cx) =
        cx.add_window_view(|window, cx| TabGroup::new(NodeId::from_u64(1), window, cx));

    let names = names.to_vec();
    let log = log.clone();
    let panels = cx.update(|window, cx| {
        let panels: Vec<_> = names
            .iter()
            .map(|name| TestPanel::logging(name, &log, cx))
            .collect();
        let views: Vec<Arc<dyn PanelView>> = panels
            .iter()
            .map(|panel| Arc::new(panel.clone()) as Arc<dyn PanelView>)
            .collect();
        group.update(cx, |group, cx| {
            // A freshly built group is sealed; place it beside siblings so
            // tests that do not care about constraints get a working group.
            group.set_constraints(TabGroupConstraints::in_split(false), window, cx);
            group.sync_from_tree(views, 0, window, cx);
        });
        panels
    });

    (group, panels, cx)
}
